package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsC decimal.Decimal // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var TempRecData TempRec
var tempLines []string
var tempIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
		m = m % 100
	}
	return fmt.Sprintf("%02d", m)
}

func formatFEd(d decimal.Decimal) string {
	// PIC ZZ9.9 : 3 integer, 1 decimal
	scaled := d.Shift(1).Truncate(0).IntPart()
	absScaled := scaled
	if absScaled < 0 {
		absScaled = -absScaled
	}
	intPart := absScaled / 10
	fracPart := absScaled % 10
	intMod := intPart % 1000
	intStr := fmt.Sprintf("%03d", intMod)
	// Z suppression for first two positions
	firstNZ := -1
	for i := 0; i < 3; i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	var intFmt string
	if firstNZ == -1 {
		intFmt = "  0"
	} else {
		b := []byte(intStr)
		for i := 0; i < firstNZ; i++ {
			if i < 2 {
				b[i] = ' '
			}
		}
		intFmt = string(b)
	}
	fracFmt := fmt.Sprintf("%01d", fracPart)
	return intFmt + "." + fracFmt
}

func formatCEd(d decimal.Decimal) string {
	// PIC -ZZ9.99 : sign + 3 integer + . + 2 decimal = 7
	signChar := byte(' ')
	if d.Sign() < 0 {
		signChar = byte('-')
	}
	absd := d.Abs()
	scaled := absd.Shift(2).Truncate(0).IntPart()
	intPart := scaled / 100
	fracPart := scaled % 100
	intMod := intPart % 1000
	intStr := fmt.Sprintf("%03d", intMod)
	firstNZ := -1
	for i := 0; i < 3; i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	var intFmt string
	if firstNZ == -1 {
		intFmt = "  0"
	} else {
		b := []byte(intStr)
		for i := 0; i < firstNZ; i++ {
			if i < 2 {
				b[i] = ' '
			}
		}
		intFmt = string(b)
	}
	fracFmt := fmt.Sprintf("%02d", fracPart)
	return string([]byte{signChar}) + intFmt + "." + fracFmt
}

func ReadPara() {
	if tempIdx < len(tempLines) {
		line := tempLines[tempIdx]
		tempIdx++
		if len(line) > 8 {
			line = line[:8]
		} else if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		}
		sensor := line[0:4]
		fStr := line[4:8]
		b := make([]byte, 4)
		for i := 0; i < 4; i++ {
			c := fStr[i]
			if c >= '0' && c <= '9' {
				b[i] = c
			} else if c == ' ' {
				b[i] = '0'
			} else {
				b[i] = '0'
			}
		}
		n, _ := strconv.ParseInt(string(b), 10, 64)
		TempRecData.TcSensor = sensor
		TempRecData.TcF = decimal.New(n, -1)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	fScaled10 := TempRecData.TcF.Shift(1).Truncate(0).IntPart()
	D := fScaled10 - 320
	P := D * 50
	var scaled100 int64
	if P == 0 {
		scaled100 = 0
	} else {
		sign := int64(1)
		if P < 0 {
			sign = -1
		}
		absP := P
		if absP < 0 {
			absP = -absP
		}
		q := absP / 9
		r := absP % 9
		if r*2 >= 9 {
			q++
		}
		scaled100 = sign * q
	}
	var scaledTrunc int64
	if scaled100 == 0 {
		scaledTrunc = 0
	} else {
		sign := int64(1)
		if scaled100 < 0 {
			sign = -1
		}
		absS := scaled100
		if absS < 0 {
			absS = -absS
		}
		absS = absS % 100000
		if absS == 0 {
			scaledTrunc = 0
		} else {
			scaledTrunc = sign * absS
		}
	}
	WsC = decimal.New(scaledTrunc, -2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatFEd(TempRecData.TcF)
	WsCEd = formatCEd(WsC)
	sensor := TempRecData.TcSensor
	if len(sensor) < 4 {
		sensor = sensor + strings.Repeat(" ", 4-len(sensor))
	} else if len(sensor) > 4 {
		sensor = sensor[:4]
	}
	fmt.Printf("%s %sF %sC\n", sensor, WsFEd, WsCEd)
	ReadPara()
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	s := string(data)
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	if len(s) == 0 {
		tempLines = []string{}
	} else {
		hasTrailing := strings.HasSuffix(s, "\n")
		parts := strings.Split(s, "\n")
		if hasTrailing {
			parts = parts[:len(parts)-1]
		}
		tempLines = parts
	}
	tempIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func main() {
	MainPara()
}
